CREATE OR REPLACE FUNCTION public.ai_create_proposal(p_user_id uuid,p_thread_id uuid,p_kind text,p_payload jsonb,p_summary text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE proposal uuid; BEGIN PERFORM 1 FROM public.ai_threads WHERE id=p_thread_id AND user_id=p_user_id AND archived_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Konversationen är inte aktiv.'; END IF; UPDATE public.ai_actions SET status='cancelled',decided_at=now() WHERE thread_id=p_thread_id AND user_id=p_user_id AND status='pending' AND decided_at IS NULL; INSERT INTO public.ai_actions(thread_id,user_id,kind,payload,summary) VALUES(p_thread_id,p_user_id,p_kind,p_payload,p_summary) RETURNING id INTO proposal; RETURN proposal; END $$;
REVOKE ALL ON FUNCTION public.ai_create_proposal(uuid,uuid,text,jsonb,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ai_create_proposal(uuid,uuid,text,jsonb,text) TO service_role;
CREATE OR REPLACE FUNCTION public.ai_claim_action(p_action_id uuid,p_user_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.ai_actions%ROWTYPE; tid uuid; BEGIN SELECT thread_id INTO tid FROM public.ai_actions WHERE id=p_action_id AND user_id=p_user_id; PERFORM 1 FROM public.ai_threads WHERE id=tid FOR UPDATE; SELECT * INTO a FROM public.ai_actions WHERE id=p_action_id AND user_id=p_user_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('error','Förslaget finns inte.'); END IF; IF a.status<>'pending' OR a.decided_at IS NOT NULL THEN RETURN jsonb_build_object('error','Förslaget är redan beslutat eller behandlas.'); END IF; IF a.created_at<=now()-interval '15 minutes' THEN UPDATE public.ai_actions SET status='expired',decided_at=now() WHERE id=a.id; RETURN jsonb_build_object('expired',true,'action',to_jsonb(a)); END IF; UPDATE public.ai_actions SET decided_at=now() WHERE id=a.id; RETURN jsonb_build_object('action',to_jsonb(a)); END $$;
REVOKE ALL ON FUNCTION public.ai_claim_action(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ai_claim_action(uuid,uuid) TO service_role;